import hashlib, hmac, json
from payhook.errors import InvalidNotification
from payhook.receiver import parse_payment

secret = b"secret"
now = 1760000000
event = {"event_id": "evt", "account_id": "acct", "amount_minor": 0, "currency": "USD"}
body = json.dumps(event).encode("utf-8")

def signed(stamp, sig_body=body):
    digest = hmac.new(secret, stamp.encode("ascii") + b"." + sig_body, hashlib.sha256).hexdigest()
    return {"X-Pay-Timestamp": stamp, "X-Pay-Signature": "v1=" + digest}

assert parse_payment(body, signed(str(now + 300)), secret, now) == event
assert parse_payment(body, signed(str(now - 300)), secret, now) == event
for args in (
    (body, signed(str(now + 301)), secret, now),
    (body + b" ", signed(str(now)), secret, now),
    (body, {"X-Pay-Timestamp": str(now), "X-Pay-Signature": "v1=" + "0" * 64}, secret, now),
    (b"\xff", signed(str(now), b"\xff"), secret, now),
    (b"{", signed(str(now), b"{"), secret, now),
    (b"[]", signed(str(now), b"[]"), secret, now),
):
    try:
        parse_payment(*args)
    except InvalidNotification:
        pass
    else:
        raise AssertionError(f"accepted invalid request: {args!r}")

for mutation in (
    {"event_id": ""},
    {"account_id": ""},
    {"amount_minor": True},
    {"amount_minor": -1},
    {"currency": "usd"},
):
    bad_event = dict(event, **mutation)
    bad_body = json.dumps(bad_event).encode("utf-8")
    try:
        parse_payment(bad_body, signed(str(now), bad_body), secret, now)
    except InvalidNotification:
        pass
    else:
        raise AssertionError(f"accepted invalid event: {mutation!r}")
print("edge checks: OK")
